// Real reviewer calibration, not a performance benchmark or a generated investment note.
// One external review call only. The candidate statements below are human-specified
// positive/negative controls, not statements generated by the model under evaluation.
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {generateAnalysis} from '../lib/server/filing-analysis.js';
const require=createRequire(import.meta.url);
if(!process.argv.includes('--live')){
 console.log('No network call made. Use node --conditions=react-server scripts/check-report-fidelity.mjs --live to send the public MSFT fixture to the configured reviewer.');
 process.exit(0);
}
const dossier=require('../lib/research/published/MSFT.json');
const sourceFor=phrase=>{
 const found=dossier.sections.flatMap(s=>s.extracts).find(c=>c.text.includes(phrase));
 if(!found)throw Error('CALIBRATION_SOURCE_MISSING');
 return found.id;
};
const cases=[
 {id:'business',chunkId:sourceFor('Our products include operating systems'),positive:'La empresa describe productos de software, servicios en nube y dispositivos.',negative:'La empresa obtiene todos sus ingresos de suscripciones recurrentes.'},
 {id:'cash',chunkId:sourceFor('Cash from operations increased'),positive:'La empresa atribuye el aumento de caja operativa a mayores cobros y menores pagos de impuestos.',negative:'La disminución de pagos de deuda consume más caja y demuestra insolvencia.'},
 {id:'thesis',chunkId:sourceFor('Overestimation of demand'),positive:'La empresa advierte que sobreestimar demanda puede llevar a capacidad ociosa y deterioro de activos.',negative:'El riesgo de exceso de capacidad demuestra que la acción está infravalorada.'},
];
for(const row of cases)if(!dossier.sections.flatMap(s=>s.extracts).some(c=>c.id===row.chunkId))throw Error('CALIBRATION_SOURCE_MISSING');
const draft={sections:cases.map(c=>({id:c.id,findings:[c.positive,c.negative].map(text=>({kind:'interpretation',text,evidence:[{chunkId:c.chunkId}]})),
 unknowns:['¿Qué evidencia adicional podría cambiar esta lectura?'],checks:['Contrastar la lectura con los documentos originales citados.']}))};
let calls=0,networkCalls=0,providerFailure;
try {
 const result=await generateAnalysis(dossier,{diagnose:()=>{},fetcher:async(url,options)=>{
  calls++;
  if(calls===1)return Response.json({choices:[{finish_reason:'stop',message:{content:JSON.stringify(draft)}}],usage:{total_tokens:0}});
  if(networkCalls)throw Error('CALIBRATION_NETWORK_BUDGET');
  networkCalls++;const response=await fetch(url,options);
  if(!response.ok){const body=await response.clone().json().catch(()=>({}));const failed=body.error?.failed_generation;
   let shape;try{const parsed=JSON.parse(failed);shape={keys:Object.keys(parsed),reviews:parsed.reviews?.length,agenda:parsed.agenda?.length}}catch{shape={validJson:false}}
   providerFailure={status:response.status,code:body.error?.code,generatedCharacters:typeof failed==='string'?failed.length:0,shape};
  }
  return response;
 }});
 const observations=cases.flatMap(c=>[c.positive,c.negative].map((text,i)=>({id:`${c.id}:${i}`,text,expected:i===0?'retained':'excluded',
  observed:result.sections.find(s=>s.id===c.id).findings.some(f=>f.text===text)?'retained':'excluded',
  review:result.review.assessments.find(r=>r.id===`${c.id}:${i}`)})));
 const passed=observations.every(c=>c.expected===c.observed);
 console.log(JSON.stringify({purpose:'source-fidelity calibration; not usefulness or competitor superiority',
  dossierHash:createHash('sha256').update(JSON.stringify(dossier)).digest('hex'),version:result.version,model:result.review.model,
  at:result.generatedAt,networkCalls,passed,observations},null,2));
 process.exitCode=passed?0:1;
}catch(e){console.log(JSON.stringify({passed:false,networkCalls,error:e.message,stage:e.stage,providerFailure}));process.exitCode=1;}
